<script setup lang="ts">
import type { JsonValue } from '@zedflow/sdk'

const client=useClient()
import { useClient } from '@zedflow/vue'

import { onScopeDispose, computed, reactive, ref, shallowRef, watch } from 'vue'
import type { Run } from '@zedflow/sdk'

import type { ContextItem } from '@zedflow/sdk'
import ContextPreviewItems from './ContextPreviewItems.vue'
import ContextItemEditor from './ContextItemEditor.vue'
import AppDialog from '../AppDialog.vue'
import ContextDefinitionDialog from './ContextDefinitionDialog.vue'
import type { ContextProgram } from '@zedflow/sdk'
import type { WindowReference, ContextWindowDetail, WindowPatch, DetailRequest } from '@zedflow/sdk'
const props=defineProps<{run:Run;nodePath:string;captured?:{alias:string;revision:string}}>()
const emit=defineEmits<{copy:[program:ContextProgram,blockId:string]}>()
const definitionOpen=ref(false),replaceOpen=ref(false),replacement=shallowRef<ContextItem>(),destination=ref(''),destinationIndex=ref(0)
const windows=shallowRef<WindowReference[]>([]),detail=shallowRef<ContextWindowDetail>(),alias=ref(''),revision=ref(''),selected=ref(''),busy=ref(false),error=ref(''),notice=ref(''),rawOpen=ref(false)
const editorFormat=ref<'text'|'json'|'media'|'adkMessages'>('text'),editorValue=ref('')
const history=shallowRef<Record<string,string[]>>({})
let intent=0
const identity=computed(()=>`${props.run.workspaceId}/${props.run.id}/${props.nodePath}`)
const current=computed(()=>windows.value.find(item=>item.nodePath===props.nodePath&&item.alias===alias.value))
const visible=computed(()=>windows.value.filter(item=>item.nodePath===props.nodePath))
const revisions=computed(()=>[...new Set([current.value?.revision,...(history.value[alias.value]||[])].filter((value):value is string=>!!value))])
function locate(items:ContextItem[],id:string,parent:string|null=null):{item:ContextItem;parent:string|null;index:number;siblings:ContextItem[]}|undefined {for(let index=0;index<items.length;index++){const item=items[index];if(item.id===id)return{item,parent,index,siblings:items};if(item.kind==='group'){const found=locate(item.items,id,item.id);if(found)return found}}}
const selection=computed(()=>detail.value?locate(detail.value.window.items,selected.value):undefined)
function remember(value:ContextWindowDetail){history.value={...history.value,[value.alias]:[...new Set([...(history.value[value.alias]||[]),value.revision])]}}
function windowsRequest():DetailRequest<'context-windows'>{return{runId:props.run.id,workspaceId:props.run.workspaceId||'',kind:'context-windows',revision:props.run.revision}}
function windowRequest(name:string,requested?:string):DetailRequest<'context-window'>{return{runId:props.run.id,workspaceId:props.run.workspaceId||'',kind:'context-window',revision:requested||props.run.revision,query:{nodePath:props.nodePath,alias:name,...(requested?{revision:requested}:{})}}}
async function refresh(){const version=++intent,id=identity.value;busy.value=true;error.value='';try{const request=windowsRequest();client.details.invalidate(request);const result=await client.details.load(request);if(version!==intent||id!==identity.value)return;windows.value=Array.isArray(result)?result:[];if(!visible.value.some(item=>item.alias===alias.value))alias.value=visible.value[0]?.alias||'';if(alias.value)await load(alias.value,props.captured?.alias===alias.value?props.captured.revision:undefined,version)}catch(cause){if(version===intent)error.value=String(cause instanceof Error?cause.message:cause)}finally{if(version===intent)busy.value=false}}
async function load(name=alias.value,requested?:string,existingIntent?:number){const version=existingIntent??++intent,id=identity.value;busy.value=true;error.value='';try{const request=windowRequest(name,requested);if(!requested)client.details.invalidate(request);const value=await client.details.load(request);if(version!==intent||id!==identity.value)return;remember(value);detail.value=value;alias.value=name;revision.value=value.revision;if(!locate(value.window.items,selected.value))selected.value=''}catch(cause){if(version===intent)error.value=String(cause instanceof Error?cause.message:cause)}finally{if(version===intent)busy.value=false}}
async function mutate(patches:WindowPatch[]){if(!detail.value)return;const version=++intent,id=identity.value,target=detail.value,listRequest=windowsRequest(),latestRequest=windowRequest(target.alias);busy.value=true;error.value='';notice.value='';try{const updated=await client.runs.patchContextWindow(props.run.id,{id:crypto.randomUUID(),nodePath:props.nodePath,alias:target.alias,expectedRevision:target.revision,patches},{workspaceId:props.run.workspaceId||''});client.details.invalidate(listRequest);client.details.invalidate(latestRequest);if(version!==intent||id!==identity.value)return;remember(updated);detail.value=updated;revision.value=updated.revision;windows.value=windows.value.map(item=>item.nodePath===updated.nodePath&&item.alias===updated.alias?{...item,revision:updated.revision}:item);if(!locate(updated.window.items,selected.value))selected.value='';notice.value='Nouvelle révision enregistrée. Sélectionnez-la explicitement pour le prochain passage.'}catch(cause){if(version===intent)error.value=String(cause instanceof Error?cause.message:cause)}finally{if(version===intent)busy.value=false}}
async function selectNext(){if(!detail.value||!current.value)return;const version=++intent,id=identity.value,target=detail.value;busy.value=true;error.value='';notice.value='';try{await client.runs.selectContextWindow(props.run.id,{id:crypto.randomUUID(),nodePath:props.nodePath,alias:target.alias,revision:target.revision,programHash:current.value.programHash},{workspaceId:props.run.workspaceId||''});if(version===intent&&id===identity.value)notice.value=`Révision ${target.revision.slice(0,10)} sélectionnée pour le prochain passage de ce nœud.`}catch(cause){if(version===intent)error.value=String(cause instanceof Error?cause.message:cause)}finally{if(version===intent)busy.value=false}}
function editRepresentation(){if(!selection.value||selection.value.item.kind!=='fragment')return;try{const value=editorFormat.value==='text'?editorValue.value:JSON.parse(editorValue.value);void mutate([{kind:'representation',id:selected.value,format:editorFormat.value,value}])}catch{error.value='La représentation doit contenir une valeur JSON valide.'}}
function groups(items:ContextItem[],prefix=''): {id:string;label:string;items:ContextItem[]}[]{return items.flatMap(item=>item.kind==='group'&&item.id!==selected.value?[{id:item.id,label:prefix+item.label,items:item.items},...groups(item.items,`${prefix}${item.label} / `)]:[])}
const destinations=computed(()=>[{id:'',label:'Racine de la fenêtre',items:detail.value?.window.items||[]},...groups(detail.value?.window.items||[])])
const destinationSize=computed(()=>destinations.value.find(item=>item.id===destination.value)?.items.filter(item=>item.id!==selected.value).length||0)
watch(destination,()=>{destinationIndex.value=destinationSize.value})
function relocate(){if(!selection.value||!destinations.value.some(item=>item.id===destination.value))return;void mutate([{kind:'move',id:selected.value,parent:destination.value||null,index:Math.max(0,Math.min(destinationSize.value,destinationIndex.value))}])}
function beginReplace(){if(!selection.value)return;replacement.value=reactive(JSON.parse(JSON.stringify(selection.value.item))) as ContextItem;replaceOpen.value=true}
async function replace(){if(!replacement.value)return;await mutate([{kind:'replace',id:selected.value,item:replacement.value}]);if(!error.value)replaceOpen.value=false}
function move(offset:number){const item=selection.value;if(!item)return;void mutate([{kind:'move',id:item.item.id,parent:item.parent,index:item.index+offset}])}
watch(()=>[selected.value,detail.value?.revision],()=>{const item=selection.value?.item;destination.value=selection.value?.parent||'';destinationIndex.value=selection.value?.index||0;if(item?.kind==='fragment'){editorFormat.value=item.format;editorValue.value=typeof item.value==='string'?item.value:JSON.stringify(item.value,null,2)}})
watch(()=>props.captured?.revision,revision=>{if(revision&&props.captured?.alias===alias.value&&detail.value?.revision!==revision)void load(alias.value,revision)})
watch(identity,()=>{intent++;replaceOpen.value=false;windows.value=[];detail.value=undefined;history.value={};selected.value='';alias.value='';notice.value='';void refresh()},{immediate:true})

onScopeDispose(()=>{intent++})
</script>
<template><section v-if="visible.length||error" class="context-window-panel" aria-label="Fenêtre de contexte révisable"><header><strong>Fenêtre de contexte</strong><button :disabled="busy" aria-label="Actualiser les fenêtres" @click="refresh">Actualiser</button></header><p v-if="error" role="alert" class="field-error">{{error}}</p><template v-if="visible.length"><div class="ctx-row"><label>Fenêtre<select aria-label="Fenêtre à inspecter" :value="alias" :disabled="busy" @change="load(($event.target as HTMLSelectElement).value)"><option v-for="item in visible" :key="item.alias" :value="item.alias">{{item.alias}}</option></select></label><label>Révision<select aria-label="Révision de la fenêtre" :value="revision" :disabled="busy" @change="load(alias,($event.target as HTMLSelectElement).value)"><option v-for="value in revisions" :key="value" :value="value">{{value.slice(0,12)}}{{current?.revision===value?' · actuelle':''}}</option></select></label></div><template v-if="detail"><p class="muted">{{detail.entityId}} · {{detail.contentRef.slice(0,18)}}</p><p v-if="detail.revision!==current?.revision" class="muted">Révision historique immuable. Une modification doit partir de la révision actuelle.</p><ContextPreviewItems action="inspect" :items="detail.window.items" :selected="selected" @select="selected=$event"/><p v-if="!detail.window.items.length" class="muted">Cette fenêtre ne contient aucun fragment.</p><button v-if="selected" @click="definitionOpen=true">Voir la définition de ce fragment</button><fieldset v-if="selection" :disabled="busy||detail.revision!==current?.revision" class="window-fragment-editor"><legend>{{selection.item.kind==='group'?selection.item.label:'Fragment'}} · {{selected}}</legend><div class="ctx-row"><button :disabled="selection.index===0" @click="move(-1)">Monter</button><button :disabled="selection.index===selection.siblings.length-1" @click="move(1)">Descendre</button><button @click="mutate([{kind:'remove',id:selected}])">Retirer de la fenêtre</button></div><details class="window-relocate"><summary>Déplacer vers un autre groupe</summary><label>Destination<select aria-label="Groupe de destination" v-model="destination"><option v-for="target in destinations" :key="target.id" :value="target.id">{{target.label}}</option></select></label><label>Position après retrait<input aria-label="Position dans le groupe" type="number" v-model.number="destinationIndex" min="0" :max="destinationSize"/></label><button @click="relocate">Déplacer l’élément</button></details><button @click="beginReplace">Remplacer cet élément</button><template v-if="selection.item.kind==='fragment'"><label>Représentation<select aria-label="Représentation du fragment" v-model="editorFormat"><option value="text">Texte</option><option value="json">JSON</option><option value="media">Référence média</option><option value="adkMessages">Messages ADK structurés</option></select></label><label>Valeur du fragment<textarea aria-label="Valeur du fragment" v-model="editorValue" rows="5" spellcheck="false"/></label><button @click="editRepresentation">Enregistrer cette représentation</button><p class="muted">Le rôle et les sources de provenance sont conservés.</p></template></fieldset><details><summary>Sources et capacités de cette révision</summary><p v-for="(value,key) in detail.window.sourceRevisions" :key="key"><code>{{key}}</code> · {{value}}</p><pre>{{JSON.stringify(detail.window.capabilities,null,2)}}</pre><button @click="rawOpen=true">Inspecter les données complètes</button></details><button :disabled="busy" @click="selectNext">Utiliser cette révision au prochain passage</button><p class="muted">Cette action ne relance aucun flow et ne modifie aucun passage enregistré.</p></template></template><p v-if="notice" role="status" class="context-window-notice">{{notice}}</p><ContextDefinitionDialog v-if="detail" v-model:open="definitionOpen" :run-id="run.id" :workspace-id="run.workspaceId" :node-path="nodePath" :hash="detail.window.programRevision||detail.window.strategyRevision" :block-id="selected" @copy="(program,block)=>emit('copy',program,block)"/><AppDialog v-model:open="replaceOpen" title="Remplacer un élément de fenêtre" wide><p>L’identité de cet élément reste conservée. Le remplacement crée une nouvelle révision de la fenêtre.</p><ContextItemEditor v-if="replacement" v-model="replacement"/><p v-if="error" role="alert" class="field-error">{{error}}</p><footer><button :disabled="busy" @click="replace">Enregistrer le remplacement</button></footer></AppDialog><AppDialog v-model:open="rawOpen" title="Données de la fenêtre" wide><pre class="source-preview">{{JSON.stringify(detail,null,2)}}</pre></AppDialog></section></template>
<style scoped>.context-window-panel{display:flex;flex-direction:column;gap:13px;padding:16px 0;border-top:1px solid #41414b;margin-top:18px}.context-window-panel>header{display:flex;align-items:center;justify-content:space-between;font-size:13px}.context-window-panel button{font-size:11px;padding:7px 9px}.context-window-panel label{display:flex;flex-direction:column;gap:6px;font-size:11px;min-width:0}.context-window-panel label input,.context-window-panel textarea,.context-window-panel select{background:#24242b;color:#ddd;border:1px solid #44444e;border-radius:4px;padding:7px;min-width:0}.context-window-panel pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px}.context-window-panel fieldset{min-width:0;border:1px solid #494952;padding:12px;display:flex;flex-direction:column;gap:10px}.context-window-panel legend{font-size:11px;overflow-wrap:anywhere;max-width:100%}.context-window-panel .ctx-row{flex-wrap:wrap}.context-window-panel .ctx-row>label{flex:1}.context-window-panel details{font-size:11px}.context-window-panel details>summary{cursor:pointer}.context-window-notice{font-size:11px;color:#b7c8b7}</style>
